      const searchInput = document.getElementById("searchIcon");
      const icons = document.querySelectorAll(".demo-icons-list-item");

      searchInput.addEventListener("input", function () {
          const keyword = this.value.toLowerCase();

          icons.forEach(icon => {
              const iconName = icon.getAttribute("data-icon").toLowerCase();
              if (iconName.includes(keyword)) {
                  icon.style.display = ""; // tampilkan
              } else {
                  icon.style.display = "none"; // sembunyikan
              }
          });
      });
    })
